#[derive(Debug, PartialEq, Eq)]
struct Record { count: u32, flags: u32 }

fn encode(record: &Record) -> [u8; 8] {
    let mut bytes = [0; 8];
    bytes[..4].copy_from_slice(&record.count.to_le_bytes());
    bytes[4..].copy_from_slice(&record.flags.to_le_bytes());
    bytes
}

fn decode(bytes: &[u8]) -> Option<Record> {
    let bytes: &[u8; 8] = bytes.try_into().ok()?;
    Some(Record {
        count: u32::from_le_bytes(bytes[..4].try_into().ok()?),
        flags: u32::from_le_bytes(bytes[4..].try_into().ok()?),
    })
}

fn main() {
    let record = Record { count: 513, flags: 7 };
    let bytes = encode(&record);
    assert_eq!(bytes, [1, 2, 0, 0, 7, 0, 0, 0]);
    assert_eq!(decode(&bytes), Some(record));
    assert_eq!(decode(&bytes[..7]), None);
    println!("Fixed-width eight-byte record verified");
}

#[derive(Debug, PartialEq, Eq)]
enum Decision { Done, RetryAfter(u64), Stop }

fn decide(status: u16, completed_attempts: u8, server_delay: Option<u64>) -> Decision {
    if (200..300).contains(&status) { return Decision::Done; }
    if completed_attempts >= 3 || !matches!(status, 429 | 503) {
        return Decision::Stop;
    }
    match server_delay {
        Some(seconds @ 1..=60) => Decision::RetryAfter(seconds),
        Some(_) => Decision::Stop,
        None => Decision::RetryAfter(5),
    }
}

fn main() {
    assert_eq!(decide(200, 1, None), Decision::Done);
    assert_eq!(decide(429, 1, Some(30)), Decision::RetryAfter(30));
    assert_eq!(decide(503, 2, None), Decision::RetryAfter(5));
    assert_eq!(decide(503, 3, None), Decision::Stop);
    assert_eq!(decide(401, 1, None), Decision::Stop);
    assert_eq!(decide(429, 1, Some(120)), Decision::Stop);
    println!("Retry decisions are bounded and testable");
}

use std::io::{BufRead, Cursor};
