fn total(unit: u32, quantity: u32, fee: u32) -> Result<u32, &'static str> {
    let subtotal = unit.checked_mul(quantity).ok_or("subtotal overflow")?;
    subtotal.checked_add(fee).ok_or("fee overflow")
}
fn main() {
    assert_eq!(total(12, 3, 2), Ok(38));
    assert_eq!(total(u32::MAX, 2, 0), Err("subtotal overflow"));
    assert_eq!(total(u32::MAX, 1, 1), Err("fee overflow"));
    println!("Checked total: {}", total(12, 3, 2).unwrap());
}

