use std::collections::HashMap;

fn fib(n: u32, cache: &mut HashMap<u32, Option<u64>>) -> Option<u64> {
    if n > 94 { return None; }
    if let Some(answer) = cache.get(&n) { return *answer; }
    let answer = match n {
        0 => Some(0),
        1 => Some(1),
        _ => fib(n - 1, cache)
            .zip(fib(n - 2, cache))
            .and_then(|(a, b)| a.checked_add(b)),
    };
    cache.insert(n, answer);
    answer
}

fn main() {
    let mut cache = HashMap::new();
    assert_eq!(fib(10, &mut cache), Some(55));
    assert_eq!(fib(93, &mut cache), Some(12_200_160_415_121_876_738));
    assert_eq!(fib(94, &mut cache), None);
    let entries = cache.len();
    assert_eq!(fib(10, &mut cache), Some(55));
    assert_eq!(cache.len(), entries);
    assert_eq!(fib(u32::MAX, &mut cache), None);
    assert_eq!(cache.len(), entries);
    println!("{entries} cached inputs; repeated requests reuse answers");
}

use std::collections::HashMap;

#[derive(Clone, Debug, PartialEq, Eq, Hash)]
struct Key { revision: u64, query: String }

struct Scores { capacity: usize, values: HashMap<Key, u64> }

impl Scores {
    fn new(capacity: usize) -> Self {
        Self { capacity, values: HashMap::new() }
    }

    fn get_or_compute<E>(
        &mut self, key: Key, compute: impl FnOnce() -> Result<u64, E>,
    ) -> Result<u64, E> {
        if let Some(value) = self.values.get(&key) { return Ok(*value); }
        let value = compute()?;
        if self.capacity != 0 {
            if self.values.len() >= self.capacity { self.values.clear(); }
            self.values.insert(key, value);
        }
        Ok(value)
    }
}

fn main() {
    let mut cache = Scores::new(2);
    let first = Key { revision: 1, query: "rust".into() };
    let second = Key { revision: 2, query: "rust".into() };
    let mut calls = 0;
    for key in [first.clone(), first, second.clone()] {
        let value = cache.get_or_compute(key.clone(), || {
            calls += 1;
            Ok::<u64, &str>(key.revision * 10)
        }).unwrap();
        assert_eq!(value, key.revision * 10);
    }
    assert_eq!(calls, 2);
    for _ in 0..2 {
        let failed = Key { revision: 3, query: "offline".into() };
        assert_eq!(cache.get_or_compute(failed, || Err("offline")), Err("offline"));
    }
    assert_eq!(cache.values.len(), 2);
    assert_eq!(cache.get_or_compute(second, || Err("must be a hit")), Ok(20));
    let third = Key { revision: 3, query: "new".into() };
    assert_eq!(cache.get_or_compute(third, || Ok::<_, &str>(30)), Ok(30));
    assert_eq!(cache.values.len(), 1);
    let mut disabled = Scores::new(0);
    let key = Key { revision: 1, query: "fresh".into() };
    assert_eq!(disabled.get_or_compute(key, || Ok::<_, &str>(7)), Ok(7));
    assert!(disabled.values.is_empty());
    println!("Revision, retry and capacity contracts passed");
}

