use std::{env, error::Error, fs, path::PathBuf};

fn main() -> Result<(), Box<dyn Error>> {
    println!("cargo::rerun-if-changed=settings/greeting.txt");
    println!("cargo::rerun-if-env-changed=GREETING_STYLE");

    let input = fs::read_to_string("settings/greeting.txt")?;
    let greeting = input.strip_suffix("\r\n").or_else(|| input.strip_suffix('\n')).unwrap_or(&input);
    if greeting.is_empty() || greeting.contains(['\r', '\n']) {
        return Err("greeting must be one nonempty line".into());
    }
    let style = match env::var("GREETING_STYLE") {
        Ok(value) => value,
        Err(env::VarError::NotPresent) => "plain".into(),
        Err(error) => return Err(error.into()),
    };
    let greeting = match style.as_str() {
        "plain" => greeting.to_owned(),
        "upper" => greeting.to_ascii_uppercase(),
        _ => return Err("GREETING_STYLE must be plain or upper".into()),
    };
    let output = PathBuf::from(env::var_os("OUT_DIR").ok_or("OUT_DIR missing")?);
    let source = format!("pub const GREETING: &str = {greeting:?};\n");
    fs::write(output.join("generated.rs"), source)?;
    Ok(())
}

