#[derive(Debug, PartialEq)]
enum QuantityError {
    Empty,
    InvalidInteger,
    OutOfRange { value: u32 },
}

#[derive(Debug, PartialEq)]
enum QuantityError { Empty, InvalidInteger, OutOfRange { value: u32 } }

fn parse_quantity(input: &str) -> Result<u32, QuantityError> {
    let text = input.trim();
    if text.is_empty() { return Err(QuantityError::Empty); }
    let value = text.parse::<u32>()
        .map_err(|_| QuantityError::InvalidInteger)?;
    if !(1..=100).contains(&value) {
        return Err(QuantityError::OutOfRange { value });
    }
    Ok(value)
}

fn show_order(input: &str) {
    match parse_quantity(input) {
        Ok(value) => println!("Order accepted: {value} items"),
        Err(QuantityError::Empty) => println!("Enter a quantity."),
        Err(QuantityError::InvalidInteger) => println!("Use a whole number."),
        Err(QuantityError::OutOfRange { .. }) => {
            println!("Choose a quantity from 1 to 100.");
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn quantity_contract() {
        assert_eq!(parse_quantity(" "), Err(QuantityError::Empty));
        assert_eq!(parse_quantity("many"), Err(QuantityError::InvalidInteger));
        assert_eq!(parse_quantity("0"), Err(QuantityError::OutOfRange { value: 0 }));
        assert_eq!(parse_quantity(" 1 "), Ok(1));
        assert_eq!(parse_quantity("100"), Ok(100));
        assert_eq!(parse_quantity("101"), Err(QuantityError::OutOfRange { value: 101 }));
        assert_eq!(parse_quantity("999999999999999999999"), Err(QuantityError::InvalidInteger));
    }
}

